/**
 * Print an icon.
 *
 * @param string $name  Icon key.
 * @param string $class Optional class on the <svg>.
 */
function mudlet_icon( string $name, string $class = '' ): void {
	echo mudlet_get_icon( $name, $class ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
}

/**
 * An icon as a string.
 *
 * @param string $name  Icon key.
 * @param string $class Optional class on the <svg>.
 * @return string
 */
function mudlet_get_icon( string $name, string $class = '' ): string {
	$set = mudlet_icon_set();
	if ( ! isset( $set[ $name ] ) ) {
		return '';
	}
	[ $attrs, $path ] = $set[ $name ];
	return sprintf(
		'<svg %1$s%2$s aria-hidden="true">%3$s</svg>',
		$attrs,
		'' !== $class ? ' class="' . esc_attr( $class ) . '"' : '',
		$path
	);
}
